"use strict";
// Deterministic premium dashboard benchmark. No real API or customer data.
const design=require("./react-design");
const APP="import React,{useState} from 'react';\nimport {Plane,Hotel,Train,Car,Wallet,Users,ShieldCheck,Search,Download,Bell,BarChart3,Menu,X,Check,ArrowUpRight} from 'lucide-react';\nconst initial=[['Olivia Chen','Toronto → New York','Oct 24–27',1240,'Approved'],['Marcus Reid','Vancouver → Chicago','Oct 26–29',1865,'Pending'],['Sophia Patel','Montreal → Boston','Nov 02–05',692,'Approved'],['Daniel Brooks','Ottawa → Calgary','Nov 06–08',978,'Pending']];\nconst money=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:0}).format(n);\nexport default function App(){\n const [tab,setTab]=useState('Flights'),[filter,setFilter]=useState('All'),[search,setSearch]=useState(''),[rows,setRows]=useState(initial),[message,setMessage]=useState(''),[mobile,setMobile]=useState(false),[page,setPage]=useState('Overview');\n const visible=rows.filter(r=>(filter==='All'||r[4]===filter)&&r.join(' ').toLowerCase().includes(search.toLowerCase()));\n const approve=name=>{setRows(rs=>rs.map(r=>r[0]===name?[...r.slice(0,4),'Approved']:r));setMessage('Approved '+name+' (demo only)')};\n const exportCsv=()=>{const csv=[['Traveler','Route','Dates','Amount CAD','Status'],...visible].map(r=>r.map(v=>'\"'+String(v).replace(/\"/g,'\"\"')+'\"').join(',')).join('\\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.href=url;a.download='travellez-demo.csv';a.click();URL.revokeObjectURL(url);setMessage('CSV downloaded')};\n return <div className=\"min-h-screen bg-[#f7f8fc] text-slate-900\">\n <aside className={'fixed inset-y-0 left-0 z-30 w-60 border-r border-slate-200 bg-white px-5 transition-transform lg:translate-x-0 '+(mobile?'translate-x-0':'-translate-x-full')}>\n <div className=\"flex h-24 items-center justify-between\"><div className=\"flex items-center gap-2\"><div className=\"rounded-xl bg-indigo-600 p-2 text-white\"><Plane size={20}/></div><b className=\"text-2xl tracking-[-.07em]\">travellez<span className=\"text-indigo-600\">.</span></b></div><button className=\"lg:hidden\" onClick={()=>setMobile(false)} aria-label=\"Close navigation\"><X/></button></div>\n <p className=\"mb-4 mt-6 text-[10px] font-bold uppercase tracking-[.2em] text-slate-400\">Workspace</p>\n {[[BarChart3,'Overview'],[Plane,'Book travel'],[Users,'Team'],[Wallet,'Spend & reports'],[ShieldCheck,'Policies']].map(([Icon,name])=><button key={name} onClick={()=>{setPage(name);setMobile(false);if(name!=='Overview')setMessage(name+' selected — demo overview remains visible')}} className={'mb-1 flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-semibold '+(page===name?'bg-indigo-50 text-indigo-700':'text-slate-500 hover:bg-slate-50')}><Icon size={18}/>{name}</button>)}\n <div className=\"absolute bottom-5 left-5 right-5 rounded-2xl bg-indigo-50 p-4\"><ShieldCheck className=\"text-indigo-600\"/><p className=\"mt-3 text-sm font-bold\">Travel smarter</p><p className=\"mt-1 text-xs leading-5 text-slate-500\">Every journey, one effortless workspace.</p></div>\n </aside>{mobile&&<button className=\"fixed inset-0 z-20 bg-black/30 lg:hidden\" onClick={()=>setMobile(false)} aria-label=\"Close overlay\"/>}\n <main className=\"lg:pl-60\"><header className=\"flex h-20 items-center justify-between border-b border-slate-200 bg-white px-5 sm:px-9\"><div className=\"flex items-center gap-3\"><button className=\"lg:hidden\" onClick={()=>setMobile(true)} aria-label=\"Open navigation\"><Menu/></button><span className=\"text-xs text-slate-400\">Workspace</span><span className=\"text-slate-300\">/</span><b className=\"text-xs\">Overview</b></div><div className=\"flex items-center gap-4\"><span className=\"hidden rounded-full bg-emerald-50 px-3 py-1.5 text-[11px] font-bold text-emerald-700 sm:block\">● All systems operational</span><button aria-label=\"Notifications\" onClick={()=>setMessage('No new notifications')}><Bell size={19}/></button><div className=\"flex h-9 w-9 items-center justify-center rounded-full bg-indigo-100 text-xs font-bold text-indigo-700\">KT</div></div></header>\n <div className=\"mx-auto max-w-[1400px] px-5 py-9 sm:px-9\"><div className=\"flex flex-wrap items-end justify-between gap-4\"><div><p className=\"text-xs font-bold uppercase tracking-[.17em] text-indigo-600\">Wednesday, October 21, 2026</p><h1 className=\"mt-2 text-3xl font-bold tracking-[-.055em] sm:text-4xl\">Welcome back, Karan <span className=\"text-indigo-600\">✳</span></h1><p className=\"mt-2 text-sm text-slate-500\">Here's what's happening with your company's travel.</p></div><button onClick={exportCsv} className=\"flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-3 text-xs font-bold shadow-sm\"><Download size={16}/> Export report</button></div>\n <div className=\"mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4\">{[['Total travel spend','$24,860','This month',Wallet,'bg-indigo-50 text-indigo-600'],['Upcoming trips','18','Next 30 days',Plane,'bg-sky-50 text-sky-600'],['Pending approvals',String(rows.filter(r=>r[4]==='Pending').length),'Needs your review',Users,'bg-amber-50 text-amber-600'],['Policy compliance','96.8%','Company-wide',ShieldCheck,'bg-emerald-50 text-emerald-600']].map(([title,value,subtitle,Icon,color])=><div key={title} className=\"rounded-2xl border border-slate-200 bg-white p-5 shadow-sm\"><div className=\"flex items-start justify-between\"><p className=\"text-xs text-slate-500\">{title}</p><div className={'rounded-xl p-2.5 '+color}><Icon size={19}/></div></div><p className=\"mt-4 text-3xl font-bold tracking-tight\">{value}</p><p className=\"mt-2 text-xs text-slate-400\">{subtitle}</p></div>)}</div>\n <div className=\"mt-6 grid gap-6 xl:grid-cols-[1.65fr_1fr]\"><section className=\"rounded-2xl border border-slate-200 bg-white p-6 shadow-sm\"><h2 className=\"text-lg font-bold\">Book your next trip</h2><p className=\"mt-1 text-xs text-slate-400\">Everything you need, in one place.</p><div className=\"mt-6 flex flex-wrap gap-2 border-b border-slate-100 pb-4\">{[['Flights',Plane],['Hotels',Hotel],['Rail',Train],['Cars',Car]].map(([name,Icon])=><button key={name} onClick={()=>setTab(name)} className={'flex items-center gap-2 rounded-lg px-3 py-2 text-xs font-bold '+(tab===name?'bg-indigo-600 text-white':'text-slate-500 hover:bg-slate-100')}><Icon size={15}/>{name}</button>)}</div>\n <div className=\"mt-5 grid gap-4 sm:grid-cols-2\"><label className=\"text-xs font-bold text-slate-500\">From<input aria-label=\"From city\" defaultValue=\"Toronto (YYZ)\" className=\"mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 text-sm text-slate-800\"/></label><label className=\"text-xs font-bold text-slate-500\">To<input aria-label=\"To city\" placeholder=\"Where to?\" className=\"mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 text-sm text-slate-800\"/></label><label className=\"text-xs font-bold text-slate-500\">Departure<input aria-label=\"Departure date\" type=\"date\" defaultValue=\"2026-10-24\" className=\"mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 text-sm text-slate-800\"/></label><label className=\"text-xs font-bold text-slate-500\">Travelers<select aria-label=\"Travelers\" className=\"mt-2 w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-800\"><option>1 traveler · Economy</option><option>2 travelers · Economy</option><option>1 traveler · Business</option></select></label></div><button onClick={()=>setMessage('Connect a verified '+tab+' supplier API for live availability')} className=\"mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-indigo-600 py-3.5 text-sm font-bold text-white hover:bg-indigo-700\"><Search size={17}/> Search {tab.toLowerCase()}</button></section>\n <section className=\"rounded-2xl bg-[#18234c] p-7 text-white\"><div className=\"flex items-center justify-between text-xs font-semibold text-indigo-200\"><span>Monthly travel budget</span><Wallet size={19}/></div><p className=\"mt-8 text-3xl font-bold tracking-tight\">$24,860 <span className=\"text-sm font-normal text-indigo-200\">/ $40,000</span></p><div className=\"mt-6 h-2 rounded-full bg-white/15\"><div className=\"h-full w-[62%] rounded-full bg-indigo-300\"/></div><div className=\"mt-3 flex justify-between text-xs text-indigo-200\"><span>62% used</span><span>$15,140 remaining</span></div><div className=\"mt-9 border-t border-white/15 pt-6\"><p className=\"text-xs text-indigo-200\">Spend by category</p>{[['Flights','58%','$14,420'],['Hotels','31%','$7,707'],['Ground transport','11%','$2,733']].map(([name,pct,value])=><div key={name} className=\"mt-5\"><div className=\"mb-2 flex justify-between text-xs\"><span>{name}</span><b>{value}</b></div><div className=\"h-1.5 rounded-full bg-white/15\"><div className=\"h-full rounded-full bg-indigo-300\" style={{width:pct}}/></div></div>)}</div></section></div>\n <section className=\"mt-6 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm\"><div className=\"flex flex-wrap items-center justify-between gap-4 px-6 py-6\"><div><h2 className=\"text-lg font-bold\">Recent travel requests</h2><p className=\"mt-1 text-xs text-slate-400\">Manage trips and approvals.</p></div><div className=\"flex flex-wrap gap-2\"><input aria-label=\"Search trips\" value={search} onChange={e=>setSearch(e.target.value)} placeholder=\"Search trips\" className=\"w-36 rounded-xl border border-slate-200 px-3 py-2 text-xs\"/><select aria-label=\"Filter status\" value={filter} onChange={e=>setFilter(e.target.value)} className=\"rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs\"><option>All</option><option>Pending</option><option>Approved</option></select></div></div><div className=\"overflow-x-auto\"><table className=\"w-full min-w-[700px] text-left text-xs\"><thead className=\"bg-slate-50 text-[10px] uppercase tracking-wider text-slate-400\"><tr>{['Traveler','Trip','Dates','Amount','Status','Action'].map(x=><th className=\"px-6 py-4\" key={x}>{x}</th>)}</tr></thead><tbody>{visible.map(([name,route,date,amount,status])=><tr key={name} className=\"border-t border-slate-100\"><td className=\"px-6 py-4 font-bold\">{name}</td><td className=\"px-6 py-4\">{route}</td><td className=\"px-6 py-4 text-slate-500\">{date}</td><td className=\"px-6 py-4 font-bold\">{money(amount)}</td><td className=\"px-6 py-4\"><span className={'rounded-full px-3 py-1 text-[10px] font-bold '+(status==='Approved'?'bg-emerald-50 text-emerald-700':'bg-amber-50 text-amber-700')}>{status}</span></td><td className=\"px-6 py-4\">{status==='Pending'?<button className=\"rounded-lg bg-indigo-50 px-3 py-2 font-bold text-indigo-700\" onClick={()=>approve(name)}>Approve</button>:<span className=\"text-slate-400\">Complete</span>}</td></tr>)}</tbody></table>{visible.length===0&&<p className=\"p-8 text-center text-sm text-slate-500\">No matching trips</p>}</div><div className=\"border-t border-slate-100 px-6 py-4 text-xs text-slate-400\">Showing {visible.length} of {rows.length} requests</div></section>\n <p className=\"mt-6 text-center text-xs text-slate-400\">Travellez design benchmark · Fictional sample data · No real supplier bookings</p></div></main>\n {message&&<div role=\"status\" className=\"fixed bottom-5 right-5 z-50 flex items-center gap-3 rounded-xl bg-slate-900 px-5 py-4 text-xs font-bold text-white shadow-xl\"><Check size={17} className=\"text-emerald-300\"/>{message}<button onClick={()=>setMessage('')} aria-label=\"Dismiss message\"><X size={16}/></button></div>}\n </div>\n}";
function files(){const f=design.starterFiles("Travellez — Corporate Travel");f["src/App.jsx"]=APP;return f;}
module.exports={files};
